INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 28, 'theory', 'Квиз: /dev/kvm и крошечный гость');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 0, 'Какое значение должен вернуть KVM_GET_API_VERSION, чтобы программа продолжила работу?', '["Любое значение не меньше 12", "Любое положительное число", "Ровно 12", "Ровно 1"]', 2, 'Документация требует отказаться работать при любом значении, кроме 12: интерфейс стабилен, а новые возможности добавляются расширениями, которые проверяют отдельно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 1, 'На каком дескрипторе выполняют KVM_CREATE_VCPU?', '["На дескрипторе машины, который вернул KVM_CREATE_VM", "На системном дескрипторе /dev/kvm", "На дескрипторе другого процессора", "На любом из трёх уровней"]', 0, 'Системный дескриптор создаёт машины, дескриптор машины создаёт процессоры, а на дескрипторе процессора выполняют KVM_RUN. Запрос не того уровня ядро отвергает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 2, 'Почему область kvm_run нужно отображать с размером из KVM_GET_VCPU_MMAP_SIZE, а не sizeof(struct kvm_run)?', '["Потому что sizeof в C не работает со структурами ядра", "Потому что ядро проверяет подпись программы", "Потому что размер не зависит от архитектуры и версии", "Потому что область включает больше, чем структура, например страницу данных портов на x86"]', 3, 'Ядро сообщает размер всей области. На x86 за структурой лежат страница данных портов и страница объединённого MMIO, а данные KVM_EXIT_IO адресуются смещением внутри области.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 3, 'KVM_RUN вернул -1, а errno равен EINTR. Что делает монитор?', '["Считает гостя аварийно остановленным", "Вызывает KVM_RUN снова", "Закрывает дескриптор процессора", "Читает run->exit_reason как причину сбоя гостя"]', 1, 'EINTR означает, что запрос прервал необработанный сигнал, а не что гость сломался. Состояние гостя сохранено, поэтому KVM_RUN вызывают снова.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 4, 'Что означает результат 0 запроса KVM_CHECK_EXTENSION?', '["Ошибка вызова: причина в errno", "Возможность включена, данных у неё нет", "Возможность этим ядром не поддерживается", "Ядро старше версии API 12"]', 2, 'Ноль значит «не поддерживается», положительное число значит «поддерживается» и иногда несёт данные. Ошибка вызова выглядит иначе: -1 и errno.');
